                                  className="text-red-600 hover:text-red-700"
                                >
                                  거절
                                </Button>
                              </div>
                            </div>
                          </CardContent>
                        </Card>
                      ))
                    )}
                  </div>
                )}
              </div>
            </TabsContent>
