      case "approved":
        return (
          <Badge className="bg-green-100 text-green-800">
            <CheckCircle className="w-3 h-3 mr-1" />
            승인
          </Badge>
        )
      case "rejected":
        return (
          <Badge className="bg-red-100 text-red-800">
            <XCircle className="w-3 h-3 mr-1" />
            거절
          </Badge>
        )
      default:
        return <Badge variant="secondary">{status}</Badge>
    }
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <div className="bg-white border-b p-4 flex items-center justify-between">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => router.back()}
          className="p-2"
        >
          <ArrowLeft className="w-5 h-5" />
        </Button>
        <h1 className="text-lg font-semibold">제휴 신청 관리</h1>
        <div className="w-10" />
      </div>

      <div className="p-4">
        {/* 통계 카드 */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
          <Card>
            <CardContent className="p-4">
              <div className="flex items-center gap-2">
                <Clock className="w-5 h-5 text-yellow-500" />
                <div>
                  <p className="text-sm text-gray-600">검토 대기</p>
                  <p className="text-2xl font-bold text-yellow-600">
                    {applications.filter(app => app.status === 'pending').length}
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-4">
              <div className="flex items-center gap-2">
                <CheckCircle className="w-5 h-5 text-green-500" />
                <div>
                  <p className="text-sm text-gray-600">승인됨</p>
                  <p className="text-2xl font-bold text-green-600">
                    {applications.filter(app => app.status === 'approved').length}
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-4">
              <div className="flex items-center gap-2">
                <XCircle className="w-5 h-5 text-red-500" />
                <div>
                  <p className="text-sm text-gray-600">거절됨</p>
                  <p className="text-2xl font-bold text-red-600">
                    {applications.filter(app => app.status === 'rejected').length}
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* 제휴 신청 목록 */}
        <Card>
          <CardHeader>
            <CardTitle>제휴 신청 목록</CardTitle>
          </CardHeader>
          <CardContent>
            {loading ? (
              <div className="text-center py-8">로딩 중...</div>
            ) : applications.length === 0 ? (
              <div className="text-center py-8">
                <FileText className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                <p className="text-gray-600">제휴 신청이 없습니다.</p>
              </div>
            ) : (
              <div className="space-y-4">
                {applications.map((application) => (
                  <Card key={application.id} className="border-l-4 border-l-blue-500">
                    <CardContent className="p-4">
                      <div className="flex items-center justify-between">
                        <div className="flex-1">
                          <div className="flex items-center gap-3 mb-2">
                            <h3 className="font-medium text-lg">{application.companyName}</h3>
                            {getStatusBadge(application.status)}
                          </div>

                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
                            <div>
                              <p className="text-gray-600">연락처 이메일</p>
                              <p className="font-medium">{application.contactEmail}</p>
                            </div>
                            <div>
                              <p className="text-gray-600">연락처 전화번호</p>
                              <p className="font-medium">{application.contactPhone}</p>
                            </div>
                            <div>
                              <p className="text-gray-600">사업자등록번호</p>
                              <p className="font-medium">{application.businessRegistration}</p>
                            </div>
                            <div>
                              <p className="text-gray-600">스토어 링크</p>
                              <a 
                                href={application.storeLink} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="text-blue-600 hover:underline"
                              >
                                {application.storeLink}
                              </a>
                            </div>
                          </div>

                          {application.rejectionReason && (
                            <div className="mt-3 p-3 bg-red-50 border border-red-200 rounded">
                              <p className="text-sm font-medium text-red-800">거절 사유</p>
                              <p className="text-sm text-red-700">{application.rejectionReason}</p>
                            </div>
                          )}

                          <div className="mt-3 text-xs text-gray-500">
                            신청일: {new Date(application.applicationDate).toLocaleDateString('ko-KR')}
                          </div>
                        </div>

                        <div className="flex flex-col gap-2 ml-4">
                          {application.status === "pending" && (
                            <>
                              <Button
                                variant="outline"
                                size="sm"
                                onClick={() => handleAction(application, "approve")}
                                className="text-green-600 hover:text-green-700"
                              >
                                <CheckCircle className="w-4 h-4 mr-1" />
                                승인
                              </Button>
                              <Button
                                variant="outline"
                                size="sm"
                                onClick={() => handleAction(application, "reject")}
                                className="text-red-600 hover:text-red-700"
                              >
                                <XCircle className="w-4 h-4 mr-1" />
                                거절
                              </Button>
                            </>
                          )}
                          {application.status === "approved" && (
                            <Badge className="bg-green-100 text-green-800">
                              승인 완료
                            </Badge>
                          )}
                          {application.status === "rejected" && (
                            <Badge className="bg-red-100 text-red-800">
                              거절 완료
                            </Badge>
                          )}
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* 액션 다이얼로그 */}
      {isActionDialogOpen && selectedApplication && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <Card className="w-full max-w-md mx-4">
            <CardHeader>
              <CardTitle>
                {actionType === "approve" ? "제휴 신청 승인" : "제휴 신청 거절"}
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <p className="text-sm text-gray-600">
                <strong>{selectedApplication.companyName}</strong>의 제휴 신청을{" "}
                {actionType === "approve" ? "승인" : "거절"}하시겠습니까?
              </p>

              {actionType === "reject" && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    거절 사유
                  </label>
                  <textarea
                    value={rejectionReason}
                    onChange={(e) => setRejectionReason(e.target.value)}
                    className="w-full p-2 border border-gray-300 rounded-md"
                    rows={3}
                    placeholder="거절 사유를 입력해주세요"
                  />
                </div>
              )}

              <div className="flex gap-2 justify-end">
                <Button
                  variant="outline"
                  onClick={() => setIsActionDialogOpen(false)}
                  disabled={isSubmitting}
                >
                  취소
                </Button>
                <Button
                  onClick={submitAction}
                  disabled={isSubmitting}
                  className={
                    actionType === "approve"
                      ? "bg-green-600 hover:bg-green-700"
                      : "bg-red-600 hover:bg-red-700"
                  }
                >
                  {isSubmitting ? "처리 중..." : actionType === "approve" ? "승인" : "거절"}
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  )
}

"use client"

import { useState, useEffect } from "react"
import { ArrowLeft, CheckCircle, XCircle, Clock, Package, Filter } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { useRouter } from "next/navigation"

interface PartnerProduct {
  id: number
  productName: string
  productContent: string
  productImage: string
  productLink: string
  productCategory: string
  productPrice: number
  status: "pending" | "approved" | "rejected"
  partnerApplicationId: number
  partnerCompanyName?: string
  rejectionReason?: string
  submittedDate: string
  createdAt: string
  updatedAt: string
}

export default function ProductApprovalsPage() {
  const router = useRouter()
  const [products, setProducts] = useState<PartnerProduct[]>([])
  const [loading, setLoading] = useState(true)
  const [selectedProduct, setSelectedProduct] = useState<PartnerProduct | null>(null)
  const [isActionDialogOpen, setIsActionDialogOpen] = useState(false)
  const [actionType, setActionType] = useState<"approve" | "reject">("approve")
  const [rejectionReason, setRejectionReason] = useState("")
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [filterStatus, setFilterStatus] = useState<string>('all')

  useEffect(() => {
    loadProducts()
  }, [])

  const loadProducts = async () => {
    try {
      setLoading(true)
      const token = localStorage.getItem("token")
      if (!token) {
        console.error("토큰이 없습니다.")
        return
      }

      // 백엔드 API 호출 시도
      try {
        const res = await fetch("/api/admin/partner/products/approvals", {
          headers: { Authorization: `Bearer ${token}` },
        })
        if (res.ok) {
          const data = await res.json()
          setProducts(data)
          return
        }
      } catch (backendError) {
        console.warn('백엔드 API 호출 실패, mock 데이터 사용:', backendError)
      }

      // Mock 데이터 사용
      const mockProducts: PartnerProduct[] = [
        {
          id: 1,
          productName: "제휴사 상품 1",
