      alert('좋아요 토글 중 오류가 발생했습니다.')
    }
  }

  const toggleScrap = async (postId: number) => {
    try {
      const token = localStorage.getItem('token')
      if (!token) {
        alert('로그인이 필요합니다')
        return
      }

