                        <div className="text-center py-8">
                          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-gray-900 mx-auto"></div>
                          <p className="text-sm text-gray-600 mt-2">좋아요한 상품을 불러오는 중...</p>
                        </div>
                      ) : likedProducts.length > 0 ? (
                        <div>
                          <div className="flex items-center justify-between mb-4">
                            <h2 className="text-lg font-bold">좋아요한 상품</h2>
                            <span className="text-sm text-gray-600">{likedProducts.length}개 상품</span>
                          </div>
                          <div className="grid grid-cols-1 gap-4">
                            {likedProducts.map((product) => (
                              <ProductCard
                                key={product.productIdx}
                                product={product}
                                onViewDetail={handleViewProductDetail}
                                onAddToCody={addToCody}
                                onToggleLike={toggleCategoryProductLike}
                              />
                            ))}
                          </div>
                        </div>
                      ) : (
                        <div className="text-center py-8">
                          <Package className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                          <p className="text-gray-600">좋아요한 상품이 없습니다.</p>
                        </div>
                      )}
                    </div>
                  ) : selectedMajorCategory &&
                    subCategoryDetails[selectedMajorCategory as keyof typeof subCategoryDetails] &&
                    !selectedSubCategory ? (
                    <div className="p-4">
                      {/* 선택된 카테고리 제목 */}
                      <div className="flex items-center justify-between mb-4">
                        <h2 className="text-lg font-bold">{selectedMajorCategory}</h2>
                        <Button variant="ghost" size="sm" className="text-blue-600">
                          전체보기
                        </Button>
                      </div>

                      {/* 세부 카테고리 그리드 */}
                      <div className="grid grid-cols-3 gap-4">
                        {subCategoryDetails[selectedMajorCategory as keyof typeof subCategoryDetails].map(
                          (subCategory, index) => (
                            <Card 
                              key={index} 
                              className="cursor-pointer hover:shadow-md transition-shadow"
                              onClick={() => {
                                setSelectedSubCategory(subCategory.name)
                                // 현재 선택된 대분류를 직접 사용
                                const currentMajorCategory = selectedMajorCategory || '상의'
                                fetchCategoryProducts(currentMajorCategory, subCategory.name)
                              }}
                            >
                              <CardContent className="p-3 text-center">
                                <div className="w-full h-20 bg-gray-100 rounded mb-2 flex items-center justify-center overflow-hidden">
                                  <img
                                    src={subCategory.image || "/placeholder.svg"}
                                    alt={subCategory.name}
                                    className="w-full h-full object-cover"
                                  />
                                </div>
                                <h3 className="text-xs font-medium">{subCategory.name}</h3>
                              </CardContent>
                            </Card>
                          ),
                        )}
                      </div>
                    </div>
                  ) : (
                    <div className="p-4">
                      {isLoadingCategory ? (
                        <div className="text-center py-8">
                          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-gray-900 mx-auto"></div>
                          <p className="text-sm text-gray-600 mt-2">상품을 불러오는 중...</p>
                        </div>
                      ) : categoryProducts.length > 0 ? (
                        <div>
                          <div className="flex items-center justify-between mb-4">
                            <h2 className="text-lg font-bold">
                              {selectedMajorCategory}
                              {selectedSubCategory && ` > ${selectedSubCategory}`}
                            </h2>
                            <span className="text-sm text-gray-600">{categoryProducts.length}개 상품</span>
                          </div>
                          <div className="grid grid-cols-1 gap-4">
                            {categoryProducts.map((product) => (
                              <ProductCard
                                key={product.productIdx}
                                product={product}
                                onViewDetail={handleViewProductDetail}
                                onAddToCody={addToCody}
                                onToggleLike={toggleCategoryProductLike}
                              />
                            ))}
                          </div>
                        </div>
                      ) : (
                        <div className="grid grid-cols-1 gap-4">
                          {filteredProducts.map((product) => (
                            <ProductCard
                              key={product.id}
                              product={{
                                productIdx: product.id,
                                productName: product.name,
                                productContent: product.description || '',
                                productPrice: parseInt(product.price.replace(/[^\d]/g, '')) || 0,
                                productImage: product.image,
                                majorCategory: product.category || '상의',
                                subCategory: '',
                                liked: product.liked
                              }}
                              onViewDetail={handleViewProductDetail}
                              onAddToCody={addToCody}
                              onToggleLike={toggleLike}
                            />
                          ))}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </SheetContent>
      </Sheet>

      {/* My Page */}
      {/* <MyPage open={isMyPageOpen} onOpenChange={setIsMyPageOpen} /> */}

      {/* Social Login Page */}
      {/* <SocialLoginPage
        open={isSocialLoginOpen} 
        onOpenChange={setIsSocialLoginOpen} 
        onSwitchToSignup={() => {}}
      /> */}

      {/* Admin Page */}
      {/* <AdminPage isOpen={isAdminPageOpen} onClose={() => setIsAdminPageOpen(false)} userRole={userInfo?.role} /> */}

      {/* Partner Page */}
      {/* <PartnerMainPage isOpen={isPartnerPageOpen} onClose={() => setIsPartnerPageOpen(false)} userRole={userInfo?.role} /> */}

      {/* Partner Application Page */}
      {/* <PartnerApplicationStandalone isOpen={isPartnerApplicationOpen} onClose={() => setIsPartnerApplicationOpen(false)} /> */}

      {/* Product Detail Page */}
      {isProductDetailOpen && selectedProduct && (
        <ProductDetailPage
          product={selectedProduct}
          onBack={handleCloseProductDetail}
          onAddToCody={addToCody}
          onToggleLike={toggleCategoryProductLike}
        />
      )}

      {/* Notification Page */}
      <NotificationPage
        isOpen={isNotificationOpen}
        onClose={() => setIsNotificationOpen(false)}
      />

    </div>
  )
}

"use client"

import { useState, useEffect } from "react"
import { ArrowLeft, Upload, Package, Edit, Trash2, CheckCircle, XCircle, Clock, Trash } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { CATEGORY_MAP, GenderCategory, MajorCategory, SubCategory } from "@/constants/category-map"
import { useRouter } from "next/navigation"

interface PartnerProduct {
  id?: number
  productName: string
  productContent: string
  productImage: string
  productLink: string
  genderCategory: string
  majorCategory: string
  subCategory: string
  productPrice: number
  status: "pending" | "approved" | "rejected"
  submittedDate?: string
  rejectionReason?: string
  updateRequestStatus?: string
  updateRequestReason?: string
  updateRequestDate?: string
  originalProductName?: string
  originalProductContent?: string
  originalProductImage?: string
  originalProductLink?: string
  originalGenderCategory?: string
  originalMajorCategory?: string
  originalSubCategory?: string
  originalProductPrice?: number
  // 수정 요청 데이터 필드들
  requestedProductName?: string
  requestedProductContent?: string
  requestedProductImage?: string
  requestedProductLink?: string
  requestedGenderCategory?: string
  requestedMajorCategory?: string
  requestedSubCategory?: string
  requestedProductPrice?: number
  // 뷰 지표(제휴사용 노출)
  viewCount?: number
  actualViewCount?: number
}

export default function PartnerProductUploadPage() {
  const router = useRouter()
  const [products, setProducts] = useState<PartnerProduct[]>([])
  const [isFormOpen, setIsFormOpen] = useState(false)
  const [editingProduct, setEditingProduct] = useState<PartnerProduct | null>(null)
  const [form, setForm] = useState({
    productName: "",
    productContent: "",
    productImage: "",
    productLink: "",
    genderCategory: "전체",
    majorCategory: "",
    subCategory: "",
    productPrice: "",
  })
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [uploading, setUploading] = useState(false)
  const [filterStatus, setFilterStatus] = useState<string>('all')
  const [userInfo, setUserInfo] = useState<any>(null)
  const [showOriginal, setShowOriginal] = useState<{ [key: number]: boolean }>({})
  const [activeTab, setActiveTab] = useState<'all' | 'modified'>('all')

  useEffect(() => {
    // 사용자 정보 가져오기
    const fetchUserInfo = async () => {
      const token = localStorage.getItem("token")
      const res = await fetch('/api/user/info', {
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      })
      if (res.ok) {
        const data = await res.json()
        setUserInfo(data)
      }
    }
    fetchUserInfo()
    loadProducts()

    // URL 파라미터에서 edit 모드 확인
    const urlParams = new URLSearchParams(window.location.search)
    const editProductId = urlParams.get('edit')
    if (editProductId) {
      // 상품 수정 모드로 진입
      const productId = parseInt(editProductId)
      if (!isNaN(productId)) {
        // 상품 정보를 로드한 후 수정 모드로 전환
        const loadProductForEdit = async () => {
          try {
            const token = localStorage.getItem("token")
            const res = await fetch(`/api/partner/products/${productId}`, {
              headers: token ? { Authorization: `Bearer ${token}` } : {},
            })
            if (res.ok) {
              const product = await res.json()
              setEditingProduct(product)
              setForm({
                productName: product.productName,
                productContent: product.productContent,
                productImage: product.productImage,
                productLink: product.productLink,
                genderCategory: product.genderCategory,
                majorCategory: product.majorCategory,
                subCategory: product.subCategory,
                productPrice: product.productPrice.toString(),
              })
              setIsFormOpen(true)
            }
          } catch (error) {
            console.error("상품 정보 로드 실패:", error)
          }
        }
        loadProductForEdit()
      }
    }
  }, [])

  const loadProducts = async () => {
    try {
      const token = localStorage.getItem("token")
      const res = await fetch("/api/partner/products", {
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      })
      if (res.ok) {
        const data = await res.json()
        setProducts(data)
      }
    } catch (error) {
      console.error("상품 목록 로드 실패:", error)
    }
  }

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    const formData = new FormData()
    formData.append("file", file)
    formData.append("purpose", "product_image")
    formData.append("refId", editingProduct?.id?.toString() || "0")

    setUploading(true)
    try {
      const token = localStorage.getItem("token")
      const res = await fetch("/api/media/upload", {
        method: "POST",
        body: formData,
        headers: {
          Authorization: `Bearer ${token}`,
        },
      })
      if (!res.ok) {
        const errorText = await res.text()
        alert("이미지 업로드 실패: " + errorText)
        return
      }
      const { url } = await res.json()
      setForm(prev => ({ ...prev, productImage: url }))
    } finally {
      setUploading(false)
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsSubmitting(true)
    try {
      const token = localStorage.getItem("token")
      const url = editingProduct?.id 
        ? `/api/partner/products/${editingProduct.id}`
        : "/api/partner/products"
      const method = editingProduct?.id ? "PUT" : "POST"

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          ...form,
          productPrice: Number(form.productPrice),
          productCategory: form.majorCategory, // product_category를 major_category로 설정
          partnerApplicationId: userInfo?.partner_application_id ? Number(userInfo.partner_application_id) : undefined,
          storeIdx: userInfo?.store_idx || 4,  // store_idx 추가 (기본값: 주민컴퍼니)
        }),
      })

      if (res.ok) {
        alert(editingProduct?.id ? "상품이 수정되었습니다!" : "상품이 등록되었습니다!")
        // URL에서 edit 파라미터 제거
        if (window.history.pushState) {
          const newUrl = window.location.pathname
          window.history.pushState({}, '', newUrl)
        }
        handleFormClose()
        loadProducts()
      } else {
        const errorText = await res.text()
        alert("상품 등록 실패: " + errorText)
      }
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleEditProduct = (product: PartnerProduct) => {
    setEditingProduct(product)
    setForm({
      productName: product.productName,
      productContent: product.productContent,
      productImage: product.productImage,
      productLink: product.productLink,
      genderCategory: product.genderCategory,
      majorCategory: product.majorCategory,
      subCategory: product.subCategory,
      productPrice: product.productPrice.toString(),
    })
    setIsFormOpen(true)
  }

  const handleDeleteProduct = async (productId: number) => {
    if (!confirm("정말로 이 상품을 삭제하시겠습니까?")) return
    try {
      const token = localStorage.getItem("token")
      const res = await fetch(`/api/partner/products/${productId}`, {
        method: "DELETE",
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      })
      if (res.ok) {
        alert("상품이 삭제되었습니다.")
        loadProducts()
      } else {
        const errorText = await res.text()
        alert("삭제 실패: " + errorText)
      }
    } catch (err) {
      console.error(err)
      alert("삭제 중 오류 발생")
    }
  }

  const handleCancelUpdateRequest = async (productId: number) => {
    if (!confirm("수정 요청을 취소하시겠습니까?")) return
    try {
      const token = localStorage.getItem("token")
      const res = await fetch(`/api/partner/products/${productId}/update-request/cancel`, {
        method: "PUT",
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      })
      if (res.ok) {
        alert("수정 요청이 취소되었습니다.")
        loadProducts()
      } else {
        const errorText = await res.text()
        alert("취소 실패: " + errorText)
      }
    } catch (err) {
      console.error(err)
      alert("취소 중 오류 발생")
    }
  }

  const handleFormClose = () => {
    setIsFormOpen(false)
    setEditingProduct(null)
    setForm({
      productName: "",
      productContent: "",
      productImage: "",
      productLink: "",
      genderCategory: "전체",
      majorCategory: "",
      subCategory: "",
      productPrice: "",
    })
    // URL에서 edit 파라미터 제거
    if (window.history.pushState) {
      const newUrl = window.location.pathname
      window.history.pushState({}, '', newUrl)
    }
  }

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "pending":
        return (
          <Badge className="bg-yellow-100 text-yellow-800">
            <Clock className="w-3 h-3 mr-1" />
            검토중
          </Badge>
        )
      case "approved":
        return (
          <Badge className="bg-green-100 text-green-800">
            <CheckCircle className="w-3 h-3 mr-1" />
            승인
          </Badge>
        )
      case "rejected":
        return (
          <Badge className="bg-red-100 text-red-800">
            <XCircle className="w-3 h-3 mr-1" />
            거절
          </Badge>
        )
      default:
        return <Badge variant="secondary">{status}</Badge>
    }
  }

  const getUpdateRequestStatusBadge = (updateRequestStatus: string) => {
    switch (updateRequestStatus) {
      case "PENDING_UPDATE":
        return (
          <Badge className="bg-blue-100 text-blue-800">
            <Edit className="w-3 h-3 mr-1" />
            수정 요청 대기
          </Badge>
        )
      case "APPROVED_UPDATE":
        return (
          <Badge className="bg-green-100 text-green-800">
            <CheckCircle className="w-3 h-3 mr-1" />
            수정 승인됨
          </Badge>
        )
      case "REJECTED_UPDATE":
        return (
          <Badge className="bg-red-100 text-red-800">
            <XCircle className="w-3 h-3 mr-1" />
            수정 거절됨
          </Badge>
        )
      default:
        return null
    }
  }

  const toggleOriginalView = (productId: number) => {
    setShowOriginal(prev => ({
      ...prev,
      [productId]: !prev[productId]
    }))
  }

  // 수정된 상품만 필터링하는 함수
  const getModifiedProducts = () => {
    return products.filter(product => 
      product.updateRequestStatus === "APPROVED_UPDATE" || 
      product.updateRequestStatus === "REJECTED_UPDATE" ||
      product.updateRequestStatus === "PENDING_UPDATE"
    )
  }

  // 현재 탭에 따른 상품 목록
  const getCurrentProducts = () => {
    if (activeTab === 'modified') {
      return getModifiedProducts()
    }
    return products
  }

  // 상품 등록/수정 폼
  if (isFormOpen) {
    return (
      <div className="min-h-screen bg-gray-50">
        {/* Header */}
        <div className="bg-white border-b p-4 flex items-center justify-between">
          <Button
            variant="ghost"
            size="sm"
            onClick={handleFormClose}
            className="p-2"
          >
            <ArrowLeft className="w-5 h-5" />
          </Button>
          <h1 className="text-lg font-semibold">
            {editingProduct?.id ? "상품 수정" : "상품 등록"}
          </h1>
          <div></div>
        </div>

        {/* Content */}
        <div className="p-4">
          <div className="max-w-2xl mx-auto">
            <Card>
              <CardHeader>
                <CardTitle>상품 정보</CardTitle>
              </CardHeader>
              <CardContent>
                <form id="product-form" onSubmit={handleSubmit} className="space-y-6">
                  {/* 상품명 */}
                  <div className="space-y-2">
                    <Label htmlFor="productName">상품명 *</Label>
                    <Input
                      id="productName"
                      value={form.productName}
                      onChange={(e) => setForm(prev => ({ ...prev, productName: e.target.value }))}
                      placeholder="상품명을 입력하세요"
                      required
                    />
                  </div>

                  {/* 상품 설명 */}
                  <div className="space-y-2">
                    <Label htmlFor="productContent">상품 설명 *</Label>
                    <Input
                      id="productContent"
                      value={form.productContent}
                      onChange={(e) => setForm(prev => ({ ...prev, productContent: e.target.value }))}
                      placeholder="상품 설명을 입력하세요"
                      required
                    />
                  </div>

                  {/* 상품 이미지 */}
                  <div className="space-y-2">
                    <Label htmlFor="productImage">상품 이미지 *</Label>
                    <Input
                      id="productImage"
                      type="file"
                      accept="image/*"
                      onChange={handleImageUpload}
                      required={!form.productImage}
                    />
                    {uploading && <p className="text-sm text-gray-600">업로드 중...</p>}
                    {form.productImage && (
                      <div className="mt-2">
                        <img src={form.productImage} alt="상품 이미지" className="w-32 h-32 object-cover rounded" />
                      </div>
                    )}
                  </div>

                  {/* 상품 링크 */}
                  <div className="space-y-2">
                    <Label htmlFor="productLink">상품 링크 *</Label>
                    <Input
                      id="productLink"
                      type="url"
                      value={form.productLink}
                      onChange={(e) => setForm(prev => ({ ...prev, productLink: e.target.value }))}
                      placeholder="https://example.com/product"
                      required
                    />
                  </div>

                  {/* 카테고리 */}
                  <div className="space-y-2">
                    {/* 성별 */}
                    <Label>성별 *</Label>
                    <Select
                      value={form.genderCategory}
                      onValueChange={(val) => {
                        setForm(prev => ({ 
                          ...prev, 
                          genderCategory: val,
                          majorCategory: "",
                          subCategory: ""
                        }))
                      }}
                    >
                      <SelectTrigger><SelectValue placeholder="성별"/></SelectTrigger>
                      <SelectContent>
                        <SelectItem value="전체">전체</SelectItem>
                        <SelectItem value="남성">남성</SelectItem>
                        <SelectItem value="여성">여성</SelectItem>
                      </SelectContent>
                    </Select>

                    {/* 대분류 */}
                    <Label>대분류 *</Label>
                    <Select
                      value={form.majorCategory}
                      onValueChange={(val) => {
                        setForm(prev => ({ 
                          ...prev, 
                          majorCategory: val,
                          subCategory: ""
                        }))
                      }}
                    >
                      <SelectTrigger><SelectValue placeholder="대분류"/></SelectTrigger>
                      <SelectContent>
                        {Object.keys(CATEGORY_MAP[form.genderCategory as GenderCategory] || {}).map(major => (
                          <SelectItem key={major} value={major}>{major}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>

                    {/* 세분류 */}
                    <Label>세분류 *</Label>
                    <Select
                      value={form.subCategory}
                      onValueChange={(val) => setForm(prev => ({ ...prev, subCategory: val }))}
                    >
                      <SelectTrigger><SelectValue placeholder="세분류"/></SelectTrigger>
                      <SelectContent className="max-h-60 overflow-y-auto">
                        {form.majorCategory && CATEGORY_MAP[form.genderCategory as GenderCategory]?.[form.majorCategory as MajorCategory]?.map((sub: SubCategory) => (
                          <SelectItem key={sub} value={sub}>{sub}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  {/* 가격 */}
                  <div className="space-y-2">
                    <Label htmlFor="productPrice">가격 *</Label>
                    <Input
                      id="productPrice"
                      type="number"
                      min="0"
                      value={form.productPrice}
                      onChange={(e) => setForm(prev => ({ ...prev, productPrice: e.target.value }))}
                      placeholder="예: 29000"
                      required
                    />
                  </div>
                  <div className="flex justify-end">
                    <Button type="submit" disabled={isSubmitting} className="bg-blue-600 hover:bg-blue-700">
                      {isSubmitting ? "등록 중..." : (editingProduct?.id ? "수정" : "등록")}
                    </Button>
                  </div>
                </form>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    )
  }

  // 필터링된 상품 목록
  const filteredProducts = getCurrentProducts().filter(product => {
    if (filterStatus === 'all') return true
    return product.status?.toLowerCase() === filterStatus.toLowerCase()
  })

