        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => router.push('/partner-dashboard')}
          >
            대시보드로
          </Button>
          <Button
            className="bg-blue-600 hover:bg-blue-700 text-white"
            onClick={() => router.push('/partner-product-upload')}
          >
            <Plus className="w-4 h-4 mr-2" />
            상품 추가
          </Button>
        </div>
      </div>

      <div className="p-4">
