                <span className="text-sm text-gray-600">
                  읽지 않은 알림: {notifications.filter(n => !n.isRead).length}개
                </span>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={markAllAsRead}
                  disabled={!notifications.some(n => !n.isRead)}
                >
                  <Check className="w-4 h-4 mr-1" />
                  모두 읽음
                </Button>
              </div>

              {/* 알림 목록 */}
              {notifications.map((notification) => (
                <Card
                  key={notification.notificationId}
                  className={`cursor-pointer transition-colors hover:bg-gray-50 ${
                    !notification.isRead ? 'bg-blue-50 border-blue-200' : 'bg-white'
                  }`}
                  onClick={() => handleNotificationClick(notification)}
                >
                  <CardContent className="p-3">
                    <div className="flex items-start gap-3">
                      <div className="flex-shrink-0">
                        {getNotificationIcon(notification.type)}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center justify-between mb-1">
                          <span className="text-sm font-medium text-gray-900">
                            {getNotificationTitle(notification.type)}
                          </span>
                          <span className="text-xs text-gray-500">
                            {formatDate(notification.createdAt)}
                          </span>
                        </div>
                        <p className="text-sm text-gray-700 line-clamp-2">
                          {getNotificationMessage(notification)}
                        </p>
                        {!notification.isRead && (
                          <div className="w-2 h-2 bg-blue-500 rounded-full mt-2"></div>
                        )}
                      </div>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={(e) => {
                          e.stopPropagation()
                          deleteNotification(notification.notificationId)
                        }}
                        className="text-gray-400 hover:text-red-500"
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </div>

        {/* 알림 상세 모달 */}
        {selectedNotification && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
            <div className="bg-white rounded-lg p-6 max-w-md w-full mx-4">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold">
                  {getNotificationTitle(selectedNotification.type)}
                </h3>
                <Button variant="ghost" size="sm" onClick={() => setSelectedNotification(null)}>
                  <X className="w-4 h-4" />
                </Button>
              </div>
              <div className="mb-4">
                <p className="text-gray-700">{getNotificationMessage(selectedNotification)}</p>
                <p className="text-sm text-gray-500 mt-2">
                  {formatDate(selectedNotification.createdAt)}
                </p>
              </div>
              <div className="flex justify-end gap-2">
                <Button variant="outline" onClick={() => setSelectedNotification(null)}>
                  닫기
                </Button>
                {selectedNotification.type === 'LIKE' && (
                  <Button onClick={() => {
                    handleLikeNotificationClick(selectedNotification)
                    setSelectedNotification(null)
                  }}>
                    게시글 보기
                  </Button>
                )}
              </div>
            </div>
          </div>
        )}
      </SheetContent>
    </Sheet>
  )
}

"use client"

import { useState, useEffect } from "react"
import { ArrowLeft, Upload, FileText, CheckCircle, XCircle, Clock } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"

interface PartnerApplication {
  id?: number
  companyName: string
  contactEmail: string
  contactPhone: string
  businessRegistration: string
  businessRegistrationFile?: string
  applicationDate?: string
  status: "pending" | "approved" | "rejected"
  rejectionReason?: string
  documents?: string[]
}

interface PartnerApplicationPageProps {
  isOpen: boolean
  onClose: () => void
}

export default function PartnerApplicationPage({ isOpen, onClose }: PartnerApplicationPageProps) {
  const [application, setApplication] = useState<PartnerApplication | null>(null)
  const [form, setForm] = useState({
    companyName: "",
    contactEmail: "",
    contactPhone: "",
    businessRegistration: "",
  })
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [uploading, setUploading] = useState(false)

  useEffect(() => {
    // 기존 신청이 있는지 확인
    loadApplication()
  }, [])

  const loadApplication = async () => {
    try {
      const token = localStorage.getItem("token")
      const res = await fetch("/api/partner/application", {
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      })
      if (res.ok) {
        const data = await res.json()
        if (data) {
          setApplication(data)
          setForm({
            companyName: data.companyName || "",
            contactEmail: data.contactEmail || "",
            contactPhone: data.contactPhone || "",
            businessRegistration: data.businessRegistration || "",
          })
        } else {
          // 신청이 없는 경우 기본 상태 유지
          setApplication(null)
        }
      } else {
        console.error("신청 정보 로드 실패:", res.status, res.statusText)
        // API 실패 시 기본 폼 상태 유지
      }
    } catch (error) {
      console.error("신청 정보 로드 실패:", error)
      // 네트워크 에러 시 기본 폼 상태 유지
    }
  }

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    const formData = new FormData()
    formData.append("file", file)
    formData.append("purpose", "partner_application")
    formData.append("refId", "0")

    setUploading(true)
    try {
      const token = localStorage.getItem("token")
      const res = await fetch("/api/media/upload", {
        method: "POST",
        body: formData,
        headers: {
          Authorization: `Bearer ${token}`,
        },
      })
      if (!res.ok) {
        const errorText = await res.text()
        alert("파일 업로드 실패: " + errorText)
        return
      }
      const { url } = await res.json()
      setForm(prev => ({ ...prev, businessRegistration: url }))
    } finally {
      setUploading(false)
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsSubmitting(true)
    try {
      const token = localStorage.getItem("token")
      const url = application?.id 
        ? `/api/partner/application/${application.id}`
        : "/api/partner/application"
      const method = application?.id ? "PUT" : "POST"

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(form),
      })

      if (res.ok) {
        alert(application?.id ? "신청이 수정되었습니다!" : "신청이 제출되었습니다!")
        loadApplication()
      } else {
        const errorText = await res.text()
        alert("신청 실패: " + errorText)
      }
    } finally {
      setIsSubmitting(false)
    }
  }

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "pending":
        return (
          <Badge className="bg-yellow-100 text-yellow-800">
            <Clock className="w-3 h-3 mr-1" />
            검토중
          </Badge>
        )
      case "approved":
        return (
          <Badge className="bg-green-100 text-green-800">
            <CheckCircle className="w-3 h-3 mr-1" />
            승인
          </Badge>
        )
      case "rejected":
        return (
          <Badge className="bg-red-100 text-red-800">
            <XCircle className="w-3 h-3 mr-1" />
            거절
          </Badge>
        )
      default:
        return <Badge variant="secondary">{status}</Badge>
    }
  }

  if (!isOpen) return null

  return (
    <div className="h-full flex flex-col">
      {/* Content */}
      <div className="flex-1 overflow-y-auto p-4">
        <div className="max-w-2xl mx-auto">
          <Card>
            <CardHeader>
              <CardTitle>제휴사 정보</CardTitle>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-6">
                {/* 회사명 */}
                <div className="space-y-2">
                  <Label htmlFor="companyName">회사명 *</Label>
                  <Input
                    id="companyName"
                    value={form.companyName}
                    onChange={(e) => setForm(prev => ({ ...prev, companyName: e.target.value }))}
                    placeholder="회사명을 입력하세요"
                    required
                  />
                </div>

                {/* 연락처 이메일 */}
                <div className="space-y-2">
                  <Label htmlFor="contactEmail">연락처 이메일 *</Label>
                  <Input
                    id="contactEmail"
                    type="email"
                    value={form.contactEmail}
                    onChange={(e) => setForm(prev => ({ ...prev, contactEmail: e.target.value }))}
                    placeholder="contact@company.com"
                    required
                  />
                </div>

                {/* 연락처 전화번호 */}
                <div className="space-y-2">
                  <Label htmlFor="contactPhone">연락처 전화번호 *</Label>
                  <Input
                    id="contactPhone"
                    type="tel"
                    value={form.contactPhone}
                    onChange={(e) => setForm(prev => ({ ...prev, contactPhone: e.target.value }))}
                    placeholder="010-1234-5678"
                    required
                  />
                </div>

                {/* 사업자등록번호 */}
                <div className="space-y-2">
                  <Label htmlFor="businessRegistration">사업자등록번호 *</Label>
                  <Input
                    id="businessRegistration"
                    value={form.businessRegistration}
                    onChange={(e) => setForm(prev => ({ ...prev, businessRegistration: e.target.value }))}
                    placeholder="123-45-67890"
                    required
                  />
                </div>

                {/* 사업자등록증 업로드 */}
                <div className="space-y-2">
                  <Label htmlFor="businessRegistrationFile">사업자등록증 *</Label>
                  <Input
                    id="businessRegistrationFile"
                    type="file"
                    accept=".pdf,.jpg,.jpeg,.png"
                    onChange={handleFileUpload}
                    required={!form.businessRegistration}
                  />
                  {uploading && <p className="text-sm text-gray-600">업로드 중...</p>}
                  {form.businessRegistration && (
                    <div className="flex items-center gap-2">
                      <FileText className="w-4 h-4 text-green-600" />
                      <span className="text-sm text-green-600">파일이 업로드되었습니다</span>
                    </div>
                  )}
                </div>

                {/* 제출 버튼 */}
                <div className="flex justify-end">
                  <Button 
                    type="submit" 
                    disabled={isSubmitting || uploading}
                    className="bg-blue-600 hover:bg-blue-700"
                  >
                    {isSubmitting ? "제출 중..." : (application?.id ? "수정" : "신청 제출")}
                  </Button>
                </div>
              </form>
            </CardContent>
          </Card>

          {/* 신청 상태 정보 */}
          {application ? (
            <Card className="mt-6">
              <CardHeader>
                <CardTitle>신청 상태</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <span className="text-sm font-medium">신청일</span>
                    <span className="text-sm text-gray-600">
                      {application.applicationDate ? new Date(application.applicationDate).toLocaleDateString('ko-KR') : "신청일 없음"}
                    </span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-sm font-medium">상태</span>
                    {getStatusBadge(application.status)}
                  </div>
                  {application.status === "rejected" && (
                    <div className="p-3 bg-red-50 border border-red-200 rounded">
                      <Label className="text-sm font-medium text-red-800">거절 사유</Label>
                      <p className="text-sm text-red-700 mt-1">
                        {application.rejectionReason || "거절 사유가 없습니다."}
                      </p>
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>
          ) : (
            <Card className="mt-6">
              <CardHeader>
                <CardTitle>신청 상태</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-center py-4">
                  <p className="text-sm text-gray-500">아직 신청을 제출하지 않았습니다.</p>
                </div>
              </CardContent>
            </Card>
          )}
        </div>
      </div>
    </div>
  )
}

"use client"

import { useState, useEffect } from "react"
import { ArrowLeft, Upload, Package, Edit, Trash2, CheckCircle, XCircle, Clock, Trash } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { CATEGORY_MAP, GenderCategory, MajorCategory, SubCategory } from "@/constants/category-map"

interface PartnerProduct {
  id?: number
  productName: string
  productContent: string
  productImage: string
  productLink: string
  genderCategory: string
  majorCategory: string
  subCategory: string
  productPrice: number
  status: "pending" | "approved" | "rejected"
  submittedDate?: string
  rejectionReason?: string
  updateRequestStatus?: string
  updateRequestReason?: string
  updateRequestDate?: string
  originalProductName?: string
  originalProductContent?: string
  originalProductImage?: string
  originalProductLink?: string
  originalGenderCategory?: string
  originalMajorCategory?: string
  originalSubCategory?: string
  originalProductPrice?: number
  // 수정 요청 데이터 필드들
  requestedProductName?: string
  requestedProductContent?: string
  requestedProductImage?: string
  requestedProductLink?: string
  requestedGenderCategory?: string
  requestedMajorCategory?: string
  requestedSubCategory?: string
  requestedProductPrice?: number
  // 뷰 지표(제휴사용 노출)
  viewCount?: number
  actualViewCount?: number
}

interface PartnerProductUploadPageProps {
  isOpen: boolean
  onClose: () => void
}

export default function PartnerProductUploadPage({ isOpen, onClose }: PartnerProductUploadPageProps) {
  const [products, setProducts] = useState<PartnerProduct[]>([])
  const [isFormOpen, setIsFormOpen] = useState(false)
  const [editingProduct, setEditingProduct] = useState<PartnerProduct | null>(null)
  const [form, setForm] = useState({
    productName: "",
    productContent: "",
    productImage: "",
    productLink: "",
    genderCategory: "전체",
    majorCategory: "",
    subCategory: "",
    productPrice: "",
  })
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [uploading, setUploading] = useState(false)
  const [filterStatus, setFilterStatus] = useState<string>('all')
  const [userInfo, setUserInfo] = useState<any>(null)
  const [showOriginal, setShowOriginal] = useState<{ [key: number]: boolean }>({})
  const [activeTab, setActiveTab] = useState<'all' | 'modified'>('all')

  useEffect(() => {
    // 사용자 정보 가져오기
    const fetchUserInfo = async () => {
      const token = localStorage.getItem("token")
      const res = await fetch('/api/user/info', {
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      })
      if (res.ok) {
        const data = await res.json()
        setUserInfo(data)
      }
    }
    fetchUserInfo()
    loadProducts()
  }, [])

  const loadProducts = async () => {
    try {
      const token = localStorage.getItem("token")
      const res = await fetch("/api/partner/products", {
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      })
      if (res.ok) {
        const data = await res.json()
        setProducts(data)
      }
    } catch (error) {
      console.error("상품 목록 로드 실패:", error)
    }
  }

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    const formData = new FormData()
    formData.append("file", file)
    formData.append("purpose", "product_image")
    formData.append("refId", editingProduct?.id?.toString() || "0")

    setUploading(true)
    try {
      const token = localStorage.getItem("token")
      const res = await fetch("/api/media/upload", {
        method: "POST",
        body: formData,
        headers: {
          Authorization: `Bearer ${token}`,
        },
      })
      if (!res.ok) {
        const errorText = await res.text()
        alert("이미지 업로드 실패: " + errorText)
        return
      }
      const { url } = await res.json()
      setForm(prev => ({ ...prev, productImage: url }))
    } finally {
      setUploading(false)
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsSubmitting(true)
    try {
      const token = localStorage.getItem("token")
      const url = editingProduct?.id 
        ? `/api/partner/products/${editingProduct.id}`
        : "/api/partner/products"
      const method = editingProduct?.id ? "PUT" : "POST"

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          ...form,
          productPrice: Number(form.productPrice),
          productCategory: form.majorCategory, // product_category를 major_category로 설정
          partnerApplicationId: userInfo?.partner_application_id ? Number(userInfo.partner_application_id) : undefined,
          storeIdx: userInfo?.store_idx || 4,  // store_idx 추가 (기본값: 주민컴퍼니)
        }),
      })

      if (res.ok) {
        alert(editingProduct?.id ? "상품이 수정되었습니다!" : "상품이 등록되었습니다!")
        handleFormClose()
        loadProducts()
      } else {
        const errorText = await res.text()
        alert("상품 등록 실패: " + errorText)
      }
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleEditProduct = (product: PartnerProduct) => {
    setEditingProduct(product)
    setForm({
      productName: product.productName,
      productContent: product.productContent,
      productImage: product.productImage,
      productLink: product.productLink,
      genderCategory: product.genderCategory,
      majorCategory: product.majorCategory,
      subCategory: product.subCategory,
      productPrice: product.productPrice.toString(),
    })
    setIsFormOpen(true)
  }

  const handleDeleteProduct = async (productId: number) => {
    if (!confirm("정말로 이 상품을 삭제하시겠습니까?")) return
    try {
      const token = localStorage.getItem("token")
      const res = await fetch(`/api/partner/products/${productId}`, {
        method: "DELETE",
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      })
      if (res.ok) {
        alert("상품이 삭제되었습니다.")
        loadProducts()
      } else {
        const errorText = await res.text()
        alert("삭제 실패: " + errorText)
      }
    } catch (err) {
      console.error(err)
      alert("삭제 중 오류 발생")
    }
  }

  const handleCancelUpdateRequest = async (productId: number) => {
    if (!confirm("수정 요청을 취소하시겠습니까?")) return
    try {
      const token = localStorage.getItem("token")
      const res = await fetch(`/api/partner/products/${productId}/update-request/cancel`, {
        method: "PUT",
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      })
      if (res.ok) {
        alert("수정 요청이 취소되었습니다.")
        loadProducts()
      } else {
        const errorText = await res.text()
        alert("취소 실패: " + errorText)
      }
    } catch (err) {
      console.error(err)
      alert("취소 중 오류 발생")
    }
  }

  const handleFormClose = () => {
    setIsFormOpen(false)
    setEditingProduct(null)
    setForm({
      productName: "",
      productContent: "",
      productImage: "",
      productLink: "",
      genderCategory: "전체",
      majorCategory: "",
      subCategory: "",
      productPrice: "",
    })
  }

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "pending":
        return (
          <Badge className="bg-yellow-100 text-yellow-800">
            <Clock className="w-3 h-3 mr-1" />
            검토중
          </Badge>
        )
      case "approved":
        return (
          <Badge className="bg-green-100 text-green-800">
            <CheckCircle className="w-3 h-3 mr-1" />
            승인
          </Badge>
        )
      case "rejected":
        return (
          <Badge className="bg-red-100 text-red-800">
            <XCircle className="w-3 h-3 mr-1" />
            거절
          </Badge>
        )
      default:
        return <Badge variant="secondary">{status}</Badge>
    }
  }

  const getUpdateRequestStatusBadge = (updateRequestStatus: string) => {
    switch (updateRequestStatus) {
      case "PENDING_UPDATE":
        return (
          <Badge className="bg-blue-100 text-blue-800">
            <Edit className="w-3 h-3 mr-1" />
            수정 요청 대기
          </Badge>
        )
      case "APPROVED_UPDATE":
        return (
          <Badge className="bg-green-100 text-green-800">
            <CheckCircle className="w-3 h-3 mr-1" />
            수정 승인됨
          </Badge>
        )
      case "REJECTED_UPDATE":
        return (
          <Badge className="bg-red-100 text-red-800">
            <XCircle className="w-3 h-3 mr-1" />
            수정 거절됨
          </Badge>
        )
      default:
        return null
    }
  }

  const toggleOriginalView = (productId: number) => {
    setShowOriginal(prev => ({
      ...prev,
      [productId]: !prev[productId]
    }))
  }

  // 수정된 상품만 필터링하는 함수
  const getModifiedProducts = () => {
    return products.filter(product => 
      product.updateRequestStatus === "APPROVED_UPDATE" || 
      product.updateRequestStatus === "REJECTED_UPDATE" ||
      product.updateRequestStatus === "PENDING_UPDATE"
    )
  }

  // 현재 탭에 따른 상품 목록
  const getCurrentProducts = () => {
    if (activeTab === 'modified') {
      return getModifiedProducts()
    }
    return products
  }

  if (!isOpen) return null

  // 상품 등록/수정 폼
  if (isFormOpen) {
    return (
      <div className="h-full flex flex-col">
        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4">
          <div className="max-w-2xl mx-auto">
            <Card>
              <CardHeader>
                <CardTitle>상품 정보</CardTitle>
              </CardHeader>
              <CardContent>
                <form id="product-form" onSubmit={handleSubmit} className="space-y-6">
                  {/* 상품명 */}
                  <div className="space-y-2">
                    <Label htmlFor="productName">상품명 *</Label>
                    <Input
                      id="productName"
                      value={form.productName}
                      onChange={(e) => setForm(prev => ({ ...prev, productName: e.target.value }))}
                      placeholder="상품명을 입력하세요"
                      required
                    />
                  </div>

                  {/* 상품 설명 */}
                  <div className="space-y-2">
                    <Label htmlFor="productContent">상품 설명 *</Label>
                    <Input
                      id="productContent"
                      value={form.productContent}
                      onChange={(e) => setForm(prev => ({ ...prev, productContent: e.target.value }))}
                      placeholder="상품 설명을 입력하세요"
                      required
                    />
                  </div>

                  {/* 상품 이미지 */}
                  <div className="space-y-2">
                    <Label htmlFor="productImage">상품 이미지 *</Label>
                    <Input
                      id="productImage"
                      type="file"
                      accept="image/*"
                      onChange={handleImageUpload}
                      required={!form.productImage}
                    />
                    {uploading && <p className="text-sm text-gray-600">업로드 중...</p>}
                    {form.productImage && (
                      <div className="mt-2">
                        <img src={form.productImage} alt="상품 이미지" className="w-32 h-32 object-cover rounded" />
                      </div>
                    )}
                  </div>

                  {/* 상품 링크 */}
                  <div className="space-y-2">
                    <Label htmlFor="productLink">상품 링크 *</Label>
                    <Input
                      id="productLink"
                      type="url"
                      value={form.productLink}
                      onChange={(e) => setForm(prev => ({ ...prev, productLink: e.target.value }))}
                      placeholder="https://example.com/product"
                      required
                    />
                  </div>

                  {/* 카테고리 */}
                  <div className="space-y-2">
                    {/* 성별 */}
                    <Label>성별 *</Label>
                    <Select
                      value={form.genderCategory}
                      onValueChange={(val) => {
                        setForm(prev => ({ 
                          ...prev, 
                          genderCategory: val,
                          majorCategory: "",
                          subCategory: ""
                        }))
                      }}
                    >
                      <SelectTrigger><SelectValue placeholder="성별"/></SelectTrigger>
                      <SelectContent>
                        <SelectItem value="전체">전체</SelectItem>
                        <SelectItem value="남성">남성</SelectItem>
                        <SelectItem value="여성">여성</SelectItem>
                      </SelectContent>
                    </Select>

                    {/* 대분류 */}
                    <Label>대분류 *</Label>
                    <Select
                      value={form.majorCategory}
                      onValueChange={(val) => {
                        setForm(prev => ({ 
                          ...prev, 
                          majorCategory: val,
                          subCategory: ""
                        }))
                      }}
                    >
                      <SelectTrigger><SelectValue placeholder="대분류"/></SelectTrigger>
                      <SelectContent>
                        {Object.keys(CATEGORY_MAP[form.genderCategory as GenderCategory] || {}).map(major => (
                          <SelectItem key={major} value={major}>{major}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>

                    {/* 세분류 */}
                    <Label>세분류 *</Label>
                    <Select
                      value={form.subCategory}
                      onValueChange={(val) => setForm(prev => ({ ...prev, subCategory: val }))}
                    >
                      <SelectTrigger><SelectValue placeholder="세분류"/></SelectTrigger>
                      <SelectContent className="max-h-60 overflow-y-auto">
                        {form.majorCategory && CATEGORY_MAP[form.genderCategory as GenderCategory]?.[form.majorCategory as MajorCategory]?.map((sub: SubCategory) => (
                          <SelectItem key={sub} value={sub}>{sub}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  {/* 가격 */}
                  <div className="space-y-2">
                    <Label htmlFor="productPrice">가격 *</Label>
                    <Input
                      id="productPrice"
                      type="number"
                      min="0"
                      value={form.productPrice}
                      onChange={(e) => setForm(prev => ({ ...prev, productPrice: e.target.value }))}
                      placeholder="예: 29000"
                      required
                    />
                  </div>
                  <div className="flex justify-end">
                    <Button type="submit" disabled={isSubmitting} className="bg-blue-600 hover:bg-blue-700">
                      {isSubmitting ? "등록 중..." : "등록"}
                    </Button>
                  </div>
                </form>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    )
  }

  // 필터링된 상품 목록
  const filteredProducts = getCurrentProducts().filter(product => {
    if (filterStatus === 'all') return true
    return product.status?.toLowerCase() === filterStatus.toLowerCase()
  })

  // 상품 목록 상단에 탭과 필터 UI 추가
  return (
    <div className="h-full flex flex-col">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-xl font-bold">상품 목록</h2>
        <div className="flex items-center gap-2">
          <label className="text-sm">상태</label>
          <select
            value={filterStatus}
            onChange={e => setFilterStatus(e.target.value)}
            className="border rounded px-2 py-1 text-sm"
          >
            <option value="all">전체</option>
            <option value="pending">검토중</option>
            <option value="approved">승인</option>
            <option value="rejected">거절</option>
          </select>
          <Button
            className="bg-blue-600 hover:bg-blue-700 text-white"
            onClick={() => {
              setEditingProduct(null);
              setForm({
                productName: "",
                productContent: "",
                productImage: "",
                productLink: "",
                genderCategory: "전체",
                majorCategory: "",
                subCategory: "",
                productPrice: "",
              });
              setIsFormOpen(true);
            }}
          >
            상품 추가
          </Button>
        </div>
      </div>

      {/* 탭 UI */}
      <div className="flex border-b mb-4">
        <button
          onClick={() => setActiveTab('all')}
          className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
            activeTab === 'all'
              ? 'border-blue-500 text-blue-600'
              : 'border-transparent text-gray-500 hover:text-gray-700'
          }`}
        >
          전체 상품 ({products.length})
        </button>
        <button
          onClick={() => setActiveTab('modified')}
          className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
            activeTab === 'modified'
              ? 'border-blue-500 text-blue-600'
              : 'border-transparent text-gray-500 hover:text-gray-700'
          }`}
        >
          수정된 상품 ({getModifiedProducts().length})
        </button>
      </div>
      {/* 상품 목록 렌더링 시 filteredProducts 사용 */}
      <div className="flex-1 overflow-y-auto p-4">
        <div className="grid gap-4">
          {filteredProducts.length === 0 ? (
            <div className="text-center py-8">
              <Package className="w-12 h-12 text-gray-400 mx-auto mb-4" />
              <p className="text-gray-600">등록된 상품이 없습니다.</p>
              <Button onClick={() => setIsFormOpen(true)} className="mt-4">
                첫 상품 등록하기
              </Button>
            </div>
          ) : (
            filteredProducts.map((product) => (
              <Card key={product.id}>
                <CardContent className="p-4">
                  <div className="flex items-center gap-4">
                    <img
                      src={product.productImage || "/placeholder.svg"}
                      alt={product.productName}
                      className="w-16 h-16 object-cover rounded"
                    />
                    <div className="flex-1">
                      <h3 className="font-medium">{product.productName}</h3>
                      <p className="text-sm text-gray-600 mb-1">{product.productContent}</p>
                                                      <div className="flex items-center gap-2 flex-wrap">
                                  <Badge variant="outline">{product.genderCategory} / {product.majorCategory} / {product.subCategory}</Badge>
                                  <span className="text-sm font-medium">₩{product.productPrice?.toLocaleString()}</span>
                                  {typeof product.viewCount === 'number' && (
                                    <span className="text-xs text-gray-600">누적 {product.viewCount.toLocaleString()}</span>
                                  )}
                                  {typeof product.actualViewCount === 'number' && (
                                    <span className="text-xs text-gray-600">실제(12h) {product.actualViewCount.toLocaleString()}</span>
                                  )}
                                  {getStatusBadge(product.status)}
                                  {product.updateRequestStatus && getUpdateRequestStatusBadge(product.updateRequestStatus)}
                                </div>
                      {product.status === "rejected" && product.rejectionReason && (
                        <div className="mt-2 p-2 bg-red-50 border border-red-200 rounded">
                          <Label className="text-sm font-medium text-red-800">거절 사유</Label>
                          <p className="text-sm text-red-700 mt-1">{product.rejectionReason}</p>
                        </div>
                      )}
                      {product.updateRequestStatus === "PENDING_UPDATE" && (
                        <div className="mt-2 p-2 bg-blue-50 border border-blue-200 rounded">
                          <div className="flex items-center justify-between mb-2">
                            <Label className="text-sm font-medium text-blue-800">수정 요청 대기 중</Label>
                          </div>
                          <table className="w-full border text-sm">
                            <thead>
                              <tr>
                                <th className="w-20 bg-gray-50">항목</th>
                                <th className="bg-gray-50">현재</th>
                                <th className="bg-gray-50">요청</th>
                              </tr>
                            </thead>
                            <tbody>
                              {[
                                { label: "상품명", before: product.productName, after: product.requestedProductName },
                                { label: "설명", before: product.productContent, after: product.requestedProductContent },
                                { label: "카테고리", before: [product.genderCategory, product.majorCategory, product.subCategory].filter(Boolean).join(" / "), after: [product.requestedGenderCategory, product.requestedMajorCategory, product.requestedSubCategory].filter(Boolean).join(" / ") },
                                { label: "가격", before: product.productPrice?.toLocaleString(), after: product.requestedProductPrice?.toLocaleString() },
                                { label: "링크", before: product.productLink, after: product.requestedProductLink },
                              ].map(({ label, before, after }) => (
                                <tr key={label}>
                                  <td className="font-medium text-gray-700 bg-gray-50">{label}</td>
                                  <td className="px-2 py-1 border-r">{before}</td>
                                  <td className={`px-2 py-1 ${before !== after ? "bg-green-100 font-semibold" : ""}`}>{after}</td>
                                </tr>
                              ))}
                              {/* 이미지 비교 */}
                              <tr>
                                <td className="font-medium text-gray-700 bg-gray-50">이미지</td>
                                <td className="px-2 py-1 border-r">
                                  {product.productImage ? (
                                    <img 
                                      src={product.productImage} 
                                      alt="현재 이미지" 
                                      className="w-12 h-12 object-cover rounded"
                                    />
                                  ) : (
                                    <span className="text-gray-400">없음</span>
                                  )}
                                </td>
                                <td className={`px-2 py-1 ${product.productImage !== product.requestedProductImage ? "bg-green-100 font-semibold" : ""}`}>
                                  {product.requestedProductImage ? (
                                    <img 
                                      src={product.requestedProductImage} 
                                      alt="요청 이미지" 
                                      className="w-12 h-12 object-cover rounded"
                                    />
                                  ) : (
                                    <span className="text-gray-400">없음</span>
                                  )}
                                </td>
                              </tr>
                            </tbody>
                          </table>
                        </div>
                      )}
                      {product.updateRequestStatus === "APPROVED_UPDATE" && activeTab === 'all' && (
                        <div className="mt-2 p-2 bg-green-50 border border-green-200 rounded">
                          <Label className="text-sm font-medium text-green-800">수정 승인됨</Label>
                          <p className="text-sm text-green-700 mt-1">수정 요청이 승인되었습니다.</p>
                        </div>
                      )}
                      {product.updateRequestStatus === "REJECTED_UPDATE" && activeTab === 'all' && (
                        <div className="mt-2 p-2 bg-red-50 border border-red-200 rounded">
                          <Label className="text-sm font-medium text-red-800">수정 거절됨</Label>
                          <p className="text-sm text-red-700 mt-1">{product.rejectionReason || "수정 요청이 거절되었습니다."}</p>
                        </div>
                      )}
                      {activeTab === 'modified' && product.updateRequestStatus === "APPROVED_UPDATE" && (
                        <div className="mt-2 p-2 bg-green-50 border border-green-200 rounded">
                          <Label className="text-sm font-medium text-green-800">✓ 수정 완료</Label>
                        </div>
                      )}
                      {activeTab === 'modified' && product.updateRequestStatus === "REJECTED_UPDATE" && (
                        <div className="mt-2 p-2 bg-red-50 border border-red-200 rounded">
                          <Label className="text-sm font-medium text-red-800">✗ 수정 거절</Label>
                          {product.rejectionReason && (
                            <p className="text-sm text-red-700 mt-1">사유: {product.rejectionReason}</p>
                          )}
                        </div>
                      )}
                    </div>
                    <div className="flex items-center gap-2">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleEditProduct(product)}
                        disabled={product.updateRequestStatus === "PENDING_UPDATE"}
                      >
                        <Edit className="w-4 h-4" />
                      </Button>
                      {product.updateRequestStatus === "PENDING_UPDATE" && (
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleCancelUpdateRequest(product.id!)}
                          className="text-orange-600 hover:text-orange-700"
                        >
                          수정 요청 취소
                        </Button>
                      )}
                      <Button
                        variant="destructive"
                        size="sm"
                        onClick={() => handleDeleteProduct(product.id!)}
                      >
                        <Trash className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </div>
      </div>
    </div>
  )
}

"use client"

import type React from "react"

import { useState, useRef, useEffect } from "react"
import { ArrowLeft, Bold, Italic, Underline, Strikethrough, ImageIcon, Palette, Upload, X, User } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Card, CardContent } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { useCreatePost } from "@/hooks/useCreatePost"

interface PostCreatePageProps {
  isOpen: boolean
  onClose: () => void
}

interface UploadedImage {
  id: string
  url: string
  file: File
  uploading: boolean
}

export default function PostCreatePage({ isOpen, onClose }: PostCreatePageProps) {
  const [title, setTitle] = useState("")
  const [content, setContent] = useState("")
  const [tags, setTags] = useState<string[]>([])
  const [newTag, setNewTag] = useState("")
  const [isDragOver, setIsDragOver] = useState(false)
  const [uploadedImages, setUploadedImages] = useState<UploadedImage[]>([])
  const fileInputRef = useRef<HTMLInputElement>(null)
  const editorRef = useRef<HTMLDivElement>(null)
  const [isEmpty, setIsEmpty] = useState(true);
  const placeholder = "내용을 입력하세요...";
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  // 게시글 생성 훅 사용
  const { createPost, loading, error, resetError } = useCreatePost();

  // 로그인 상태 확인
  useEffect(() => {
    const token = localStorage.getItem('token');
    setIsLoggedIn(!!token);
  }, []);

  // 에디터 초기화
  useEffect(() => {
    if (editorRef.current) {
      editorRef.current.innerHTML = content
      editorRef.current.focus()
    }
  }, [])

  const handleAddTag = () => {
    if (newTag.trim() && !tags.includes(newTag.trim())) {
      setTags([...tags, newTag.trim()])
      setNewTag("")
    }
  }

  const handleRemoveTag = (tagToRemove: string) => {
    setTags(tags.filter((tag) => tag !== tagToRemove))
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      e.preventDefault()
      handleAddTag()
    }
  }

  // S3에 이미지 업로드
  const uploadImageToS3 = async (file: File): Promise<string> => {
    const formData = new FormData()
    formData.append('file', file)
    formData.append('purpose', 'post_image')
    formData.append('refId', Date.now().toString()) // 임시 refId

    // 인증 토큰 가져오기
    const token = localStorage.getItem('token')
    if (!token) {
      throw new Error('로그인이 필요합니다.')
    }

    const response = await fetch('/api/media/upload', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${token}`,
      },
      body: formData,
    })

    if (!response.ok) {
      if (response.status === 401) {
        throw new Error('인증이 만료되었습니다. 다시 로그인해주세요.')
      }
      throw new Error('이미지 업로드에 실패했습니다.')
    }

    const result = await response.json()
    return result.url
  }

  // 이미지 업로드 처리
  const handleImageUpload = async (files: FileList) => {
    Array.from(files).forEach(async (file) => {
      if (file.type.startsWith("image/")) {
        // 임시 이미지 객체 생성 (업로드 중 상태)
        const tempImage = {
          id: Date.now().toString(),
          url: "",
          file: file,
          uploading: true
        }

        setUploadedImages((prev) => [...prev, tempImage])

        try {
          // S3에 업로드
          const imageUrl = await uploadImageToS3(file)

          // 업로드 성공 시 URL 업데이트
          setUploadedImages((prev) => 
            prev.map(img => 
              img.id === tempImage.id 
                ? { ...img, url: imageUrl, uploading: false }
                : img
            )
          )
        } catch (error) {
          console.error('이미지 업로드 실패:', error)
          // 업로드 실패 시 제거
          setUploadedImages((prev) => prev.filter(img => img.id !== tempImage.id))
          alert('이미지 업로드에 실패했습니다.')
        }
      }
    })
  }

  // 드래그 앤 드롭 처리
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(true)
  }

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(false)
  }

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(false)
    const files = e.dataTransfer.files
    if (files.length > 0) {
      handleImageUpload(files)
    }
  }

  // 파일 선택 처리
  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (files) {
      handleImageUpload(files)
    }
  }

  // 이미지 삭제
  const handleRemoveImage = (id: string) => {
    setUploadedImages(uploadedImages.filter((img) => img.id !== id))
  }

  // 텍스트 스타일 적용
  const applyTextStyle = (command: string, value?: string) => {
    document.execCommand(command, false, value)
    if (editorRef.current) {
      setContent(editorRef.current.innerHTML)
      editorRef.current.focus()
    }
  }

  // 에디터 내용 변경 처리
  const handleEditorChange = () => {
    if (editorRef.current) {
      setContent(editorRef.current.innerHTML)
    }
  }

  const handleEditorInput = (e: React.FormEvent<HTMLDivElement>) => {
    const textContent = e.currentTarget.textContent;
    setIsEmpty(!textContent || textContent.trim() === "");
    handleEditorChange(); // 기존 함수도 호출
  };

  // 게시글 발행
  const handlePublish = async () => {
    if (!title.trim()) {
      alert("제목을 입력해주세요.")
      return
    }

    if (!content.trim() && uploadedImages.length === 0) {
      alert("내용을 입력하거나 이미지를 업로드해주세요.")
      return
    }

    // 업로드 중인 이미지가 있는지 확인
    const hasUploadingImages = uploadedImages.some(img => img.uploading)
    if (hasUploadingImages) {
      alert("이미지 업로드가 완료될 때까지 기다려주세요.")
      return
    }

    try {
      // S3에 업로드된 이미지 URL들만 추출
      const mediaUrls = uploadedImages
        .filter(img => img.url && !img.uploading)
        .map(img => img.url);

      const postData = {
        title: title.trim(),
        content: content.trim(),
        tags: tags,
        mediaUrls: mediaUrls
      };

      console.log('게시글 발행 시작:', postData);

      const result = await createPost(postData);

      if (result) {
        alert("게시글이 발행되었습니다!")
        onClose();
      } else {
        alert("게시글 발행에 실패했습니다. 다시 시도해주세요.");
      }
    } catch (err) {
      console.error('게시글 발행 에러:', err);
      alert("게시글 발행 중 오류가 발생했습니다.");
    }
  }

  if (!isOpen) return null

  // 로그인이 필요한 경우
  if (!isLoggedIn) {
    return (
      <div className="fixed inset-0 bg-white z-50 flex flex-col h-screen">
        {/* Header */}
        <div className="bg-white border-b p-4 flex items-center justify-between flex-shrink-0">
          <div className="flex items-center gap-3">
            <Button variant="ghost" size="sm" onClick={onClose} className="p-1 h-8 w-8">
              <ArrowLeft className="w-5 h-5" />
            </Button>
            <h1 className="text-xl font-bold">글 작성</h1>
          </div>
        </div>

        {/* Content */}
        <div className="flex-1 flex items-center justify-center">
          <div className="text-center space-y-4">
            <div className="w-16 h-16 mx-auto bg-gray-100 rounded-full flex items-center justify-center">
              <User className="w-8 h-8 text-gray-400" />
            </div>
            <h2 className="text-xl font-semibold">로그인이 필요합니다</h2>
            <p className="text-gray-600">게시글을 작성하려면 로그인해주세요.</p>
