"use client"

import { useState, useEffect, useCallback, useRef } from "react"
import { ArrowLeft, Heart, MessageSquare, Bookmark, Share2, MoreHorizontal, Send, Plus } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Input } from "@/components/ui/input"
import { Badge } from "@/components/ui/badge"
import { Card } from "@/components/ui/card"

interface Comment {
  id: number
  author: string
  authorImage: string
  content: string
  date: string
  likes: number
  liked?: boolean
}

interface Post {
  postId: number
  title: string
  content: string
  authorName: string
  authorProfileImage: string
  mediaUrls: string[]
  likeCount: number
  commentCount: number
  scrapCount: number
  createdAt: string
  tags: string[]
  liked?: boolean
  scraped?: boolean
  type?: string
}

interface PostDetailProps {
  isOpen: boolean
  onClose: () => void
  postId: number
}

export default function PostDetailPage({ isOpen, onClose, postId }: PostDetailProps) {
  const [posts, setPosts] = useState<Post[]>([])
  const [loading, setLoading] = useState(false)
  const [hasMore, setHasMore] = useState(true)
  const [currentPage, setCurrentPage] = useState(0)
  const [commentText, setCommentText] = useState("")
  const [comments, setComments] = useState<Comment[]>([])
  const [isLiked, setIsLiked] = useState(false)
  const [isScraped, setIsScraped] = useState(false)
  const [isFollowing, setIsFollowing] = useState(false)
  const [currentPost, setCurrentPost] = useState<Post | null>(null)
  const observer = useRef<IntersectionObserver | null>(null)

  // 게시글 목록 가져오기
  const fetchPosts = useCallback(async (page: number = 0) => {
    if (loading || !hasMore) return

    setLoading(true)
    try {
      const response = await fetch(`http://localhost:8080/api/posts?page=${page}&size=10`)
      if (response.ok) {
        const data = await response.json()
        const newPosts = data.content || []

        // Post 타입에 맞게 데이터 변환
        const transformedPosts = newPosts.map((post: any) => ({
          postId: post.postId,
          title: post.title || "",
          content: post.content,
          authorName: post.authorName || "익명",
          authorProfileImage: post.authorProfileImage || "/placeholder.svg",
          mediaUrls: post.mediaUrls || [],
          likeCount: post.likeCount || 0,
          commentCount: post.commentCount || 0,
          scrapCount: post.scrapCount || 0,
          createdAt: post.createdAt,
          tags: post.tags || [],
          liked: post.isLiked || false,
          scraped: post.isScrapped || false,
          type: post.type || "fashion-tip"
        }))

        if (page === 0) {
          setPosts(transformedPosts)
        } else {
          setPosts(prev => [...prev, ...transformedPosts])
        }

        setHasMore(!data.last)
        setCurrentPage(page)

        // 현재 게시글 찾기
        if (page === 0) {
          const targetPost = transformedPosts.find((p: Post) => p.postId === postId)
          if (targetPost) {
            setCurrentPost(targetPost)
            setIsLiked(targetPost.liked || false)
            setIsScraped(targetPost.scraped || false)
          }
        }

        console.log('게시글 로드 성공:', transformedPosts)
      } else {
        console.error('게시글 로드 실패:', response.status)
      }
    } catch (error) {
      console.error('게시글 로드 중 오류:', error)
    } finally {
      setLoading(false)
    }
  }, [loading, hasMore, postId])

  // 무한 스크롤을 위한 마지막 요소 관찰
  const lastPostElementRef = useCallback((node: HTMLDivElement) => {
    if (loading) return

    if (observer.current) observer.current.disconnect()

    observer.current = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && hasMore) {
        fetchPosts(currentPage + 1)
      }
    })

    if (node) observer.current.observe(node)
  }, [loading, hasMore, currentPage, fetchPosts])

  // 컴포넌트 마운트 시 게시글 로드
  useEffect(() => {
    if (isOpen) {
      fetchPosts(0)
    }
  }, [isOpen, fetchPosts])

  const toggleLike = (postId: number) => {
    setPosts(prev => 
      prev.map(post => 
        post.postId === postId 
          ? { ...post, liked: !post.liked, likeCount: post.liked ? post.likeCount - 1 : post.likeCount + 1 }
          : post
      )
    )

    if (currentPost?.postId === postId) {
      setIsLiked(!isLiked)
    }
  }

  const toggleScrap = (postId: number) => {
    setPosts(prev => 
      prev.map(post => 
        post.postId === postId 
          ? { ...post, scraped: !post.scraped, scrapCount: post.scraped ? post.scrapCount - 1 : post.scrapCount + 1 }
          : post
      )
    )

    if (currentPost?.postId === postId) {
      setIsScraped(!isScraped)
    }
  }

  const toggleFollow = () => {
    setIsFollowing(!isFollowing)
  }

  const handleCommentSubmit = () => {
    if (commentText.trim()) {
      const newComment: Comment = {
        id: Date.now(),
        author: "나",
        authorImage: "/placeholder.svg",
        content: commentText,
        date: new Date().toISOString(),
        likes: 0,
        liked: false
      }
      setComments([...comments, newComment])
      setCommentText("")
    }
  }

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    const now = new Date()
    const diffTime = Math.abs(now.getTime() - date.getTime())
    const diffHours = Math.ceil(diffTime / (1000 * 60 * 60))

    if (diffHours < 1) return "방금 전"
    if (diffHours === 1) return "1시간 전"
    if (diffHours < 24) return `${diffHours}시간 전`
    return `${Math.ceil(diffHours / 24)}일 전`
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 bg-white z-50 flex flex-col h-screen">
      {/* Header */}
      <div className="bg-white border-b p-4 flex items-center justify-between flex-shrink-0">
        <Button variant="ghost" size="sm" onClick={onClose} className="p-1 h-8 w-8">
          <ArrowLeft className="w-5 h-5" />
        </Button>
        <div className="font-bold text-lg">커뮤니티</div>
        <Button variant="ghost" size="sm">
          <MoreHorizontal className="w-5 h-5" />
        </Button>
      </div>

      {/* Posts Feed */}
      <div className="flex-1 overflow-y-auto">
        {posts.map((post, index) => (
          <div 
            key={post.postId} 
            ref={index === posts.length - 1 ? lastPostElementRef : undefined}
            className="border-b"
          >
            {/* User Info */}
            <div className="p-4">
              <div className="flex items-center gap-3">
                <Avatar className="w-12 h-12">
                  <AvatarImage src={post.authorProfileImage} />
                  <AvatarFallback>{post.authorName?.charAt(0)}</AvatarFallback>
                </Avatar>
                <div className="flex-1">
                  <div className="font-medium">{post.authorName}</div>
                  <div className="text-sm text-gray-500">171cm/63kg · 봄 원돈</div>
                </div>
                <Button 
                  variant={isFollowing ? "outline" : "default"} 
                  size="sm"
                  onClick={toggleFollow}
                >
                  {isFollowing ? "팔로잉" : "+ 팔로우"}
                </Button>
              </div>
            </div>

            {/* Main Image */}
            <div className="relative">
              <img
                src={post.mediaUrls?.[0] || "/placeholder.svg"}
                alt={post.content.substring(0, 20)}
                className="w-full h-auto"
              />
            </div>

            {/* Interaction Buttons */}
            <div className="p-4 border-b">
              <div className="flex items-center gap-4 mb-3">
                <Button 
                  variant="ghost" 
                  size="sm" 
                  onClick={() => toggleLike(post.postId)} 
                  className="p-2"
                >
                  <Heart className={`w-6 h-6 ${post.liked ? "fill-red-500 text-red-500" : ""}`} />
                </Button>
                <Button variant="ghost" size="sm" className="p-2">
                  <MessageSquare className="w-6 h-6" />
                </Button>
                <Button variant="ghost" size="sm" className="p-2">
                  <Share2 className="w-6 h-6" />
                </Button>
                <div className="ml-auto">
                  <Button 
                    variant="ghost" 
                    size="sm" 
                    onClick={() => toggleScrap(post.postId)} 
                    className="p-2"
                  >
                    <Bookmark className={`w-6 h-6 ${post.scraped ? "fill-blue-500 text-blue-500" : ""}`} />
                  </Button>
                </div>
              </div>
              <div className="text-sm font-medium">좋아요 {post.likeCount}개</div>
            </div>

            {/* Tags */}
            {post.tags && post.tags.length > 0 && (
              <div className="p-4 border-b">
                <div className="flex flex-wrap gap-2">
                  {post.tags.map((tag: string, index: number) => (
                    <Badge key={index} variant="secondary" className="text-sm">
                      #{tag}
                    </Badge>
                  ))}
                </div>
              </div>
            )}

            {/* Comments */}
            <div className="p-4 border-b">
              <div className="text-sm text-gray-500 mb-4">
                {post.commentCount === 0 ? "첫 댓글을 남겨주세요." : `댓글 ${post.commentCount}개`}
              </div>
            </div>

            {/* Post Time */}
            <div className="p-4 text-sm text-gray-500">
              {formatDate(post.createdAt)}
            </div>
          </div>
        ))}

        {/* Loading Indicator */}
        {loading && (
          <div className="p-4 text-center text-gray-500">
            게시글을 불러오는 중...
          </div>
        )}

        {/* End of Feed */}
        {!hasMore && posts.length > 0 && (
          <div className="p-4 text-center text-gray-500">
            모든 게시글을 불러왔습니다
          </div>
        )}
      </div>

      {/* Comment Input */}
      <div className="border-t bg-white p-4 flex-shrink-0">
        <div className="flex gap-2">
          <Input
            placeholder="댓글을 입력하세요..."
            value={commentText}
            onChange={(e) => setCommentText(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleCommentSubmit()}
            className="flex-1"
          />
          <Button onClick={handleCommentSubmit} disabled={!commentText.trim()}>
            <Send className="w-4 h-4" />
          </Button>
        </div>
      </div>
    </div>
  )
}

"use client"

import { useState, useEffect } from "react"
import { ArrowLeft, CheckCircle, XCircle, Clock, Package } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { getProductApprovals, approveProduct } from "../actions/admin-actions"
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"
import { Input } from "@/components/ui/input"

interface ProductApproval {
  id: number
  product_name: string
  store_name: string
  images: string[]
  description: string
  price: string
  category: string
  status: "pending" | "approved" | "rejected"
  submitted_date: string
}

interface ProductApprovalPageProps {
  isOpen: boolean
  onClose: () => void
}

export default function ProductApprovalPage({ isOpen, onClose }: ProductApprovalPageProps) {
  const [approvals, setApprovals] = useState<ProductApproval[]>([])
  const [loading, setLoading] = useState(false)
  const [selectedIds, setSelectedIds] = useState<number[]>([])
  const [isBulkDialogOpen, setIsBulkDialogOpen] = useState(false)
  const [bulkAction, setBulkAction] = useState<'approve' | 'reject'>('approve')
  const [bulkRejectionReason, setBulkRejectionReason] = useState('')
  const [isBulkSubmitting, setIsBulkSubmitting] = useState(false)

  useEffect(() => {
    if (isOpen) {
      loadApprovals()
    }
  }, [isOpen])

  const loadApprovals = async () => {
    setLoading(true)
    try {
      const data = await getProductApprovals()
      setApprovals(data)
    } catch (error) {
      console.error("승인 대기 상품 로드 실패:", error)
    } finally {
      setLoading(false)
    }
  }

  const handleApprove = async (productId: number, approved: boolean) => {
    const action = approved ? "승인" : "거절"
    if (confirm(`이 상품을 ${action}하시겠습니까?`)) {
      const result = await approveProduct(productId, approved)
      if (result.success) {
        alert(result.message)
        loadApprovals()
      } else {
        alert(result.message)
      }
    }
  }

  // 일괄 승인/거절 핸들러
  const handleBulkAction = (action: 'approve' | 'reject') => {
    setBulkAction(action)
    setBulkRejectionReason('')
    setIsBulkDialogOpen(true)
  }

  const submitBulkAction = async () => {
    setIsBulkSubmitting(true)
    try {
      const token = localStorage.getItem('token')
      const res = await fetch('/api/admin/products/bulk-status', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          ids: selectedIds,
          action: bulkAction,
          rejectionReason: bulkAction === 'reject' ? bulkRejectionReason : undefined,
        }),
      })
      if (res.ok) {
        alert(`상품이 ${bulkAction === 'approve' ? '일괄 승인' : '일괄 거절'}되었습니다.`)
        setSelectedIds([])
        setIsBulkDialogOpen(false)
        loadApprovals()
      } else {
        const errorText = await res.text()
        alert('일괄 처리 실패: ' + errorText)
      }
    } finally {
      setIsBulkSubmitting(false)
    }
  }

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "pending":
        return (
          <Badge className="bg-yellow-100 text-yellow-800">
            <Clock className="w-3 h-3 mr-1" />
            검토중
          </Badge>
        )
      case "approved":
        return (
          <Badge className="bg-green-100 text-green-800">
            <CheckCircle className="w-3 h-3 mr-1" />
            승인
          </Badge>
        )
      case "rejected":
        return (
          <Badge className="bg-red-100 text-red-800">
            <XCircle className="w-3 h-3 mr-1" />
            거절
          </Badge>
        )
      default:
        return <Badge variant="secondary">{status}</Badge>
    }
  }

  const pendingApprovals = approvals.filter((approval) => approval.status === "pending")
  const processedApprovals = approvals.filter((approval) => approval.status !== "pending")

  if (!isOpen) return null

  // 체크박스 핸들러
  const toggleSelect = (id: number) => {
    setSelectedIds((prev) => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id])
  }
  const selectAll = () => setSelectedIds(pendingApprovals.map(a => a.id))
  const deselectAll = () => setSelectedIds([])

  return (
    <div className="fixed inset-0 bg-white z-50 flex flex-col h-screen">
      {/* Header */}
      <div className="bg-white border-b p-4 flex items-center justify-between flex-shrink-0">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="sm" onClick={onClose} className="p-1 h-8 w-8">
            <ArrowLeft className="w-5 h-5" />
          </Button>
          <h1 className="text-xl font-bold">상품 승인 관리</h1>
        </div>
        <Badge variant="secondary">Product Approval</Badge>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-4">
        <div className="space-y-6">
          {/* 요약 통계 */}
          <div className="grid grid-cols-3 gap-4">
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-gray-600">전체 상품</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">{approvals.length}</div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-gray-600">승인 대기</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-yellow-600">{pendingApprovals.length}</div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-gray-600">처리 완료</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-green-600">{processedApprovals.length}</div>
              </CardContent>
            </Card>
          </div>

          {/* 승인 대기 상품 */}
          <div className="space-y-4">
            <div className="flex items-center gap-2 mb-2">
              <Button size="sm" variant="outline" onClick={selectAll}>전체 선택</Button>
              <Button size="sm" variant="outline" onClick={deselectAll}>선택 해제</Button>
              <Button size="sm" className="bg-green-600 hover:bg-green-700 text-white" disabled={selectedIds.length === 0} onClick={() => handleBulkAction('approve')}>일괄 승인</Button>
              <Button size="sm" className="bg-red-600 hover:bg-red-700 text-white" disabled={selectedIds.length === 0} onClick={() => handleBulkAction('reject')}>일괄 거절</Button>
              <span className="text-sm text-gray-500">선택: {selectedIds.length}개</span>
            </div>
            {loading ? (
              <div className="text-center py-8">로딩 중...</div>
            ) : pendingApprovals.length === 0 ? (
              <Card>
                <CardContent className="p-8 text-center text-gray-500">
                  <Package className="w-12 h-12 mx-auto mb-4 text-gray-400" />
                  <p>승인 대기 중인 상품이 없습니다.</p>
                </CardContent>
              </Card>
            ) : (
              <div className="space-y-4">
                {pendingApprovals.map((approval) => (
                  <Card key={approval.id} className="border-yellow-200">
                    <CardContent className="p-4">
                      <div className="space-y-4">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            <input type="checkbox" checked={selectedIds.includes(approval.id)} onChange={() => toggleSelect(approval.id)} />
                            <h3 className="font-medium text-lg">{approval.product_name}</h3>
                            <p className="text-sm text-gray-600">{approval.store_name}</p>
                          </div>
                          {getStatusBadge(approval.status)}
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {/* 상품 이미지 */}
                          <div className="space-y-2">
                            <span className="text-sm font-medium text-gray-600">상품 이미지:</span>
                            <div className="grid grid-cols-2 gap-2">
                              {approval.images.map((image, index) => (
                                <div key={index} className="w-full h-24 border rounded overflow-hidden">
                                  <img
                                    src={image || "/placeholder.svg"}
                                    alt={`상품 이미지 ${index + 1}`}
                                    className="w-full h-full object-cover"
                                  />
                                </div>
                              ))}
                            </div>
                          </div>

                          {/* 상품 정보 */}
                          <div className="space-y-3">
                            <div>
                              <span className="text-sm font-medium text-gray-600">카테고리:</span>
                              <Badge variant="outline" className="ml-2">
                                {approval.category}
                              </Badge>
                            </div>

                            <div>
                              <span className="text-sm font-medium text-gray-600">가격:</span>
                              <span className="ml-2 font-medium">{approval.price}</span>
                            </div>

                            <div>
                              <span className="text-sm font-medium text-gray-600">제출일:</span>
                              <span className="ml-2">{approval.submitted_date}</span>
                            </div>
                          </div>
                        </div>

                        <div className="space-y-2">
                          <span className="text-sm font-medium text-gray-600">상품 설명:</span>
                          <p className="text-sm bg-gray-50 p-3 rounded">{approval.description}</p>
                        </div>

                        <div className="flex items-center justify-end gap-2 pt-2 border-t">
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleApprove(approval.id, false)}
                            className="text-red-600 hover:text-red-700"
                          >
                            <XCircle className="w-4 h-4 mr-1" />
                            거절
                          </Button>
                          <Button
                            size="sm"
                            onClick={() => handleApprove(approval.id, true)}
                            className="bg-green-600 hover:bg-green-700"
                          >
                            <CheckCircle className="w-4 h-4 mr-1" />
                            승인
                          </Button>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            )}
          </div>

          {/* 처리 완료 상품 */}
          {processedApprovals.length > 0 && (
            <div className="space-y-4">
              <h2 className="text-lg font-semibold flex items-center gap-2">
                <CheckCircle className="w-5 h-5 text-green-600" />
                처리 완료 ({processedApprovals.length})
              </h2>

              <div className="space-y-4">
                {processedApprovals.map((approval) => (
                  <Card key={approval.id} className="bg-gray-50">
                    <CardContent className="p-4">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                          <img
                            src={approval.images[0] || "/placeholder.svg"}
                            alt={approval.product_name}
                            className="w-12 h-12 object-cover rounded"
                          />
                          <div>
                            <h3 className="font-medium">{approval.product_name}</h3>
                            <p className="text-sm text-gray-600">{approval.store_name}</p>
                          </div>
                        </div>
                        <div className="text-right">
                          {getStatusBadge(approval.status)}
                          <p className="text-xs text-gray-500 mt-1">{approval.submitted_date}</p>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* 일괄 거절/승인 다이얼로그 */}
      <Dialog open={isBulkDialogOpen} onOpenChange={setIsBulkDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {bulkAction === 'approve' ? '일괄 승인' : '일괄 거절'}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <p className="text-sm text-gray-600 mb-2">
              {bulkAction === 'approve'
                ? `${selectedIds.length}개의 상품을 일괄 승인하시겠습니까?`
                : `${selectedIds.length}개의 상품을 일괄 거절하시겠습니까?`}
            </p>
            {bulkAction === 'reject' && (
              <div className="space-y-2">
                <Label htmlFor="bulkRejectionReason">거절 사유 *</Label>
                <Input
                  id="bulkRejectionReason"
                  value={bulkRejectionReason}
                  onChange={e => setBulkRejectionReason(e.target.value)}
                  placeholder="거절 사유를 입력하세요"
                />
              </div>
            )}
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setIsBulkDialogOpen(false)} disabled={isBulkSubmitting}>취소</Button>
              <Button
                onClick={submitBulkAction}
                disabled={isBulkSubmitting || (bulkAction === 'reject' && !bulkRejectionReason)}
                className={bulkAction === 'approve' ? 'bg-green-600 hover:bg-green-700' : 'bg-red-600 hover:bg-red-700'}
              >
                {isBulkSubmitting ? '처리 중...' : (bulkAction === 'approve' ? '일괄 승인' : '일괄 거절')}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}

"use client"

import type React from "react"

import { useState, useEffect } from "react"
import { ArrowLeft, Upload, X } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { addProduct, updateProduct } from "../actions/admin-actions"
import { CATEGORY_MAP, GenderCategory, MajorCategory, SubCategory } from "@/constants/category-map";

interface Product {
  id?: number
  product_name: string
  product_content: string
  product_image: string
  product_link: string
  majorCategory: string
  subCategory: string
  genderCategory: string
  store_mall: string
  price: string
  created_at?: string
}

interface StoreMall {
  id?: number
  storeIdx?: number
  storeName: string
  contact: string
  storeLink: string
  royaltyRate: number
  storeLogo: string
  isActive?: boolean
  createdAt?: string
  updatedAt?: string
}

interface ProductFormProps {
  isOpen: boolean
  onClose: () => void
  editingProduct?: Product | null | undefined
  storeMalls: StoreMall[]
}

const categories = ["상의", "하의", "아우터", "신발", "가방", "패션소품"]

export default function ProductForm({ isOpen, onClose, editingProduct, storeMalls }: ProductFormProps) {
  const [formData, setFormData] = useState({
    product_name: editingProduct?.product_name || "",
    product_content: editingProduct?.product_content || "",
    product_image: editingProduct?.product_image || "",
    product_link: editingProduct?.product_link || "",
    major_category: editingProduct?.majorCategory || "상의",
    sub_category: editingProduct?.subCategory || "",
    gender_category: editingProduct?.genderCategory || "전체",
    store_mall: editingProduct?.store_mall || "",
    price: editingProduct?.price || "",
  })
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [imagePreview, setImagePreview] = useState(editingProduct?.product_image || "")
  const [imageUrl, setImageUrl] = useState<string | null>(null)
  const [uploading, setUploading] = useState(false)
  const [isStoreModalOpen, setIsStoreModalOpen] = useState(false);
  // selectedStore 초기값을 id 기준으로
  const [selectedStore, setSelectedStore] = useState<StoreMall | null>(null);
  const [tempSelectedStore, setTempSelectedStore] = useState<StoreMall | null>(null);

  // 상품 수정 폼이 열릴 때마다 selectedStore를 동기화
  useEffect(() => {
    if (editingProduct && storeMalls.length > 0) {
      const found = storeMalls.find(
        mall => mall.id?.toString() === editingProduct.store_mall?.toString()
      );
      setSelectedStore(found || null);
      setTempSelectedStore(found || null);
    }
  }, [editingProduct, storeMalls]);

  const handleInputChange = (field: string, value: string) => {
    setFormData((prev) => ({
      ...prev,
      [field]: value,
    }))

    if (field === "product_image") {
      setImagePreview(value)
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedStore) {
      alert("제휴몰을 선택해야 합니다.");
      setIsSubmitting(false);
      return;
    }
    const token = localStorage.getItem("token");

    setIsSubmitting(true);
    try {
      const isEditing = editingProduct?.id;
      const url = isEditing 
        ? `/api/admin/products/${editingProduct.id}` 
        : "/api/admin/products/add";
      const method = isEditing ? "PUT" : "POST";

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          storeIdx: selectedStore?.id, // store_mall → storeIdx
          productName: formData.product_name,
          productContent: formData.product_content,
          productPrice: Number(formData.price), // 반드시 number로 변환
          productImage: formData.product_image,
          majorCategory: formData.major_category,
          subCategory: formData.sub_category,
          genderCategory: formData.gender_category,
          productLink: formData.product_link,
        }),
      });
      if (!res.ok) {
        const errorText = await res.text();
        console.error("상품 처리 에러:", errorText);
        alert(isEditing ? "상품 수정 실패: " + errorText : "상품 등록 실패: " + errorText);
        return;
      }
      const data = await res.json();
      alert(isEditing ? "상품이 수정되었습니다!" : "상품이 등록되었습니다!");
      onClose();
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const formData = new FormData();
    formData.append("file", file);
    formData.append("purpose", "product_image");
    formData.append("refId", editingProduct?.id?.toString() || "0"); // 수정 시에는 실제 상품 ID 사용
    setUploading(true);
    try {
      const res = await fetch("/api/media/upload", {
        method: "POST",
        body: formData,
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      });
      if (!res.ok) {
        const errorText = await res.text();
        console.error("업로드 에러:", errorText);
        alert("이미지 업로드 실패: " + errorText);
        return;
      }
      const { url } = await res.json();
      setImageUrl(url);
      setFormData((prev) => ({ ...prev, product_image: url }));
    } finally {
      setUploading(false);
    }
  };

  if (!isOpen) return null

  const gender = (formData.gender_category as GenderCategory) || '전체';
  const major = formData.major_category as MajorCategory;

  return (
    <div className="fixed inset-0 bg-white z-50 flex flex-col h-screen">
      {/* Header */}
      <div className="bg-white border-b p-4 flex items-center justify-between flex-shrink-0">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="sm" onClick={onClose} className="p-1 h-8 w-8">
            <ArrowLeft className="w-5 h-5" />
          </Button>
          <h1 className="text-xl font-bold">{editingProduct ? "상품 수정" : "상품 추가"}</h1>
        </div>
        {/* 상단 등록 버튼 제거 */}
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-4">
        <div className="max-w-2xl mx-auto">
          <Card>
            <CardHeader>
              <CardTitle>상품 정보</CardTitle>
            </CardHeader>
            <CardContent>
              <form id="product-form" onSubmit={handleSubmit} className="space-y-6">
                {/* 상품명 */}
                <div className="space-y-2">
                  <Label htmlFor="product_name">상품명 *</Label>
                  <Input
                    id="product_name"
                    value={formData.product_name}
                    onChange={(e) => handleInputChange("product_name", e.target.value)}
                    placeholder="상품명을 입력하세요"
                    required
                  />
                </div>

                {/* 상품 설명 */}
                <div className="space-y-2">
                  <Label htmlFor="product_name">상품 설명 *</Label>
                  <Input
                    id="product_content"
                    value={formData.product_content}
                    onChange={(e) => handleInputChange("product_content", e.target.value)}
                    placeholder="상품 설명을 입력하세요"
                    required
                  />
                </div>

                {/* 상품 이미지 */}
                <div className="space-y-2">
                  <Label htmlFor="product_image">상품 이미지 *</Label>
                  <div className="space-y-3">
                    <Input
                      id="product_image"
                      value={formData.product_image}
                      onChange={(e) => handleInputChange("product_image", e.target.value)}
                      placeholder="이미지 URL을 입력하거나 파일을 업로드하세요"
                      required
                    />

                    {/* 파일 업로드 */}
                    <div className="flex items-center gap-2">
                      <input
                        type="file"
                        accept="image/*"
                        onChange={handleImageUpload}
                        className="hidden"
                        id="image-upload"
                      />
                      <Button
                        type="button"
                        variant="outline"
                        onClick={() => document.getElementById("image-upload")?.click()}
                        className="flex items-center gap-2"
                      >
                        <Upload className="w-4 h-4" />
                        파일 업로드
                      </Button>
                    </div>

                    {/* 이미지 미리보기 */}
                    {imagePreview && (
                      <div className="relative w-32 h-32 border rounded overflow-hidden">
                        <img
                          src={imagePreview || "/placeholder.svg"}
                          alt="미리보기"
                          className="w-full h-full object-cover"
                        />
                        <Button
                          type="button"
                          variant="ghost"
                          size="sm"
                          className="absolute top-1 right-1 w-6 h-6 p-0 bg-red-500 hover:bg-red-600 text-white rounded-full"
                          onClick={() => {
                            handleInputChange("product_image", "")
                            setImagePreview("")
                          }}
                        >
                          <X className="w-3 h-3" />
                        </Button>
                      </div>
                    )}
                  </div>
                </div>

                {/* 상품 링크 */}
                <div className="space-y-2">
                  <Label htmlFor="product_link">상품 링크 *</Label>
                  <Input
                    id="product_link"
                    type="text"
                    value={formData.product_link}
                    onChange={(e) => handleInputChange("product_link", e.target.value)}
                    placeholder="https://example.com/product"
                    required
                  />
                </div>

                {/* 카테고리 */}
                <div className="space-y-2">
                  {/* 성별 */}
                  <Label>성별 *</Label>
                  <Select
                    value={formData.gender_category}
                    onValueChange={(val) => {
                      handleInputChange("gender_category", val);
                      handleInputChange("sub_category", "");
                    }}>
                    <SelectTrigger><SelectValue placeholder="성별"/></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="전체">전체</SelectItem>
                      <SelectItem value="남성">남성</SelectItem>
                      <SelectItem value="여성">여성</SelectItem>
                    </SelectContent>
                  </Select>

                  {/* 대분류 */}
                  <Label>대분류 *</Label>
                  <Select
                    value={formData.major_category}
                    onValueChange={(val)=>{
                       handleInputChange("major_category", val);
                       handleInputChange("sub_category", "");
                    }}>
                    <SelectTrigger><SelectValue placeholder="대분류"/></SelectTrigger>
                    <SelectContent>
                      {Object.keys(CATEGORY_MAP[formData.gender_category as GenderCategory] || {}).map(m=> (
                        <SelectItem key={m} value={m}>{m}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  {/* 세부 */}
                  <Label>세부 분류</Label>
                  <Select value={formData.sub_category} onValueChange={(val)=>handleInputChange("sub_category", val)}>
                    <SelectTrigger><SelectValue placeholder="세부 분류"/></SelectTrigger>
                    <SelectContent className="max-h-60 overflow-y-auto">
                      {CATEGORY_MAP[gender][major]?.map((s: SubCategory) => (
                        <SelectItem key={s} value={s}>{s}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                {/* 제휴몰 선택 (모달 방식) */}
                <div className="space-y-2">
                  <Label htmlFor="store_mall">제휴몰 *</Label>
                  <button
                    type="button"
                    className="w-full border rounded px-4 py-2 flex items-center gap-2 bg-gray-50 hover:bg-gray-100"
                    onClick={() => {
                      setTempSelectedStore(selectedStore);
                      setIsStoreModalOpen(true);
                    }}
                  >
                    {selectedStore ? (
                      <>
                        {selectedStore.storeLogo && (
                          <img src={selectedStore.storeLogo} alt={selectedStore.storeName} style={{ width: 24, height: 24, marginRight: 8, borderRadius: 4 }} />
                        )}
                        <span>{selectedStore.storeName}</span>
                        <a href={selectedStore.storeLink} target="_blank" rel="noopener noreferrer" className="ml-2 text-blue-500 underline text-xs">{selectedStore.storeLink}</a>
                      </>
                    ) : (
                      <span className="text-gray-400">제휴몰을 선택하세요</span>
                    )}
                  </button>
                  {!selectedStore && <div className="text-red-500 text-xs mt-1">제휴몰을 선택해야 합니다.</div>}
                </div>

                {/* 제휴사 선택 모달 */}
                {isStoreModalOpen && (
                  <div className="fixed inset-0 bg-black bg-opacity-30 flex items-center justify-center z-50">
                    <div className="bg-white rounded-lg shadow-lg p-8 min-w-[350px] max-w-[90vw] max-h-[80vh] overflow-y-auto">
                      <h2 className="text-lg font-bold mb-4">제휴사 선택</h2>
                      <div className="grid gap-4">
                        {storeMalls.filter(mall => mall.isActive).map((mall) => (
                          <div
                            key={mall.id}
                            className={`flex items-center gap-4 p-3 border rounded cursor-pointer ${tempSelectedStore?.id === mall.id ? 'border-blue-500 bg-blue-50' : 'border-gray-200'}`}
                            onClick={() => setTempSelectedStore(mall)}
                          >
                            {mall.storeLogo && (
                              <img src={mall.storeLogo} alt={mall.storeName} style={{ width: 40, height: 40, borderRadius: 6 }} />
                            )}
                            <div>
                              <div className="font-semibold">{mall.storeName}</div>
                              <a href={mall.storeLink} target="_blank" rel="noopener noreferrer" className="text-blue-500 underline text-xs">{mall.storeLink}</a>
                            </div>
                          </div>
                        ))}
                      </div>
                      <div className="flex justify-end gap-2 mt-6">
                        <Button
                          type="button"
                          onClick={() => {
                            setSelectedStore(tempSelectedStore);
                            // store의 id를 저장 (백엔드에서 storeIdx로 사용)
                            setFormData(prev => ({ ...prev, store_mall: tempSelectedStore?.id?.toString() || "" }));
                            setIsStoreModalOpen(false);
                          }}
                          disabled={!tempSelectedStore}
                        >
                          적용
                        </Button>
