          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        credentials: 'include'
      });

      if (response.ok) {
        const data = await response.json();

        if (data.token) {
          // localStorage에 토큰 저장
          localStorage.setItem('token', data.token);
          setUser(data);
          setIsLoggedIn(true);
          onOpenChange(false);
